   129	\section{Embeddings in Projective Space}
   130	\label{ha-ch4-s3}\source{hartshorne-algebraic-geometry:IV.3}
   131	\begin{proposition}[Linear systems]\label{ha-ch4-p31}\dcref{IV.3.1}
   132	\source{hartshorne-algebraic-geometry:IV.3.1}
   133	\(|D|\) is base-point-free iff \(\dim|D-P|=\dim|D|-1\) for all \(P\); \(D\)
   134	is very ample iff \(\dim|D-P-Q|=\dim|D|-2\) for all \(P,Q\), including
   135	\(P=Q\).
   136	\end{proposition}
   137	\begin{proof}
   138	The exact sequence at \(P\) identifies the failure of surjectivity of
   139	\(|D-P|\to|D|\) with a base point.  The closed-immersion criterion translates
   140	separation of points and tangent vectors into the two stated dimension drops.
   141	\end{proof}
   142	
   143	\begin{corollary}[Numerical bounds]\label{ha-ch4-c32}\dcref{IV.3.2}
   144	\source{hartshorne-algebraic-geometry:IV.3.2}
   145	\(\deg D\ge2g\) implies no base points, and \(\deg D\ge2g+1\) implies very
   146	ample.
   147	\uses{ha-ch4-p31}
   148	\end{corollary}
   149	\begin{proof}
   150	Riemann--Roch makes the relevant \(D-P\), respectively \(D-P-Q\), nonspecial,
   151	and Proposition 3.1 applies.
   152	\end{proof}
