  1011	\begin{proposition}[Effective Cartier divisors and closed subschemes]
  1012	\label{prop:II-6-18}
  1013	\source{hartshorne-algebraic-geometry:II.6.18}
  1014	\dcref{II.6.18}
  1015	Effective Cartier divisors on $X$ are in bijection with closed subschemes whose ideal sheaf is
  1016	invertible and locally generated by a non-zero-divisor.
  1017	\end{proposition}
  1018	\begin{proof}
  1019	The two constructions are $D\mapsto\mathcal O_X(-D)$ and an invertible ideal with a local
  1020	non-zero-divisor generator to its vanishing divisor; the constructions are inverse.
  1021	\end{proof}
