  1023	\section{Projective Morphisms}
  1024	
  1025	\begin{definition}[Projective morphism]
  1026	\label{def:II-7-projective}
  1027	\source{hartshorne-algebraic-geometry:II.7}
  1028	A morphism is projective if it factors as a closed immersion $X\hookrightarrow\mathbb P^n_Y$. An
  1029	invertible sheaf is relatively very ample when it is the pullback of $\mathcal O(1)$ under such an embedding.
  1030	\end{definition}
  1031	
  1032	\begin{theorem}[Morphisms to projective space]
  1033	\label{thm:II-7-1}
  1034	\source{hartshorne-algebraic-geometry:II.7.1}
  1035	\dcref{II.7.1}
  1036	A morphisms $f:X\to\mathbb P^n_Y$ is equivalent to an invertible sheaf $\mathcal L$ on $X$
  1037	together with generating global sections $s_0,\ldots,s_n$, up to the natural change of basis.
  1038	\end{theorem}
  1039	\begin{proof}
  1040	Pull back $\mathcal O(1)$ and its coordinate sections. Conversely, the ratios of the generating
  1041	sections define compatible maps to the standard affine charts and glue to $f$.
  1042	\end{proof}
  1043	
  1044	\begin{proposition}[Closed immersion criterion]
  1045	\label{prop:II-7-2}
  1046	\source{hartshorne-algebraic-geometry:II.7.2}
  1047	\dcref{II.7.2}
  1048	A morphism defined by generating sections of an invertible sheaf is a closed immersion precisely
  1049	when the induced maps on the standard affine opens identify their coordinate rings with the relevant
  1050	affine coordinate rings.
  1051	\end{proposition}
  1052	\begin{proof}
  1053	Check the assertion on the standard affine cover of projective space; a morphism is a closed immersion
  1054	if and only if it is so on an affine open cover of the target.
  1055	\end{proof}
  1056	
  1057	\begin{proposition}[Projective embedding criterion]
  1058	\label{prop:II-7-3}
  1059	\source{hartshorne-algebraic-geometry:II.7.3}
  1060	\dcref{II.7.3}
  1061	For a finite-type scheme over a field, a finite-dimensional space of sections of an invertible sheaf
  1062	defines a closed immersion into projective space iff it separates points and tangent vectors.
  1063	\end{proposition}
  1064	\begin{proof}
  1065	Point separation makes the map injective and an immersion on residue fields; tangent-vector separation
  1066	makes the induced local maps surjective on cotangent spaces. The affine criterion then gives a closed
  1067	immersion.
  1068	\end{proof}
  1069	
  1070	\begin{lemma}[Finite generation from local maps]
  1071	\label{lem:II-7-4}
  1072	\source{hartshorne-algebraic-geometry:II.7.4}
  1073	\dcref{II.7.4}
  1074	If a local homomorphism of noetherian local rings induces a finite extension on residue fields and
  1075	the target is generated by finitely many elements over the image, then the corresponding morphism is
  1076	finite on a neighborhood.
  1077	\end{lemma}
  1078	\begin{proof}
  1079	Choose finitely many generators and clear denominators in the localizations; Nakayama's lemma gives
  1080	finite generation after shrinking.
  1081	\end{proof}
  1082	
  1083	\begin{proposition}[Ample invertible sheaves]
  1084	\label{prop:II-7-5}
  1085	\source{hartshorne-algebraic-geometry:II.7.5}
  1086	\dcref{II.7.5}
  1087	For an invertible sheaf $\mathcal L$ on a noetherian scheme, the following are equivalent: $\mathcal L$
  1088	is ample; every coherent sheaf becomes generated by global sections after a positive twist; and a
  1089	sufficiently high power of $\mathcal L$ gives a projective embedding on every affine neighborhood.
  1090	\end{proposition}
  1091	\begin{proof}
  1092	The implications follow by applying the finite-generation lemma to affine standard opens and using
  1093	the point-and-tangent separation criterion.
  1094	\end{proof}
  1095	
  1096	\begin{theorem}[Projective implies proper]
  1097	\label{thm:II-7-6}
  1098	\source{hartshorne-algebraic-geometry:II.7.6}
  1099	\dcref{II.7.6}
  1100	Every projective morphism is proper.
  1101	\end{theorem}
  1102	\begin{proof}
  1103	The projection $\mathbb P^n_Y\to Y$ satisfies the valuative criterion by scaling homogeneous coordinates
  1104	so one is a unit in the valuation ring. Closed immersions and compositions preserve properness.
  1105	\end{proof}
  1106	
  1107	\begin{proposition}[Divisors of zeros and linear systems]
  1108	\label{prop:II-7-7}
  1109	\source{hartshorne-algebraic-geometry:II.7.7}
  1110	\dcref{II.7.7}
  1111	A nonzero section of an invertible sheaf determines an effective Cartier divisor of zeros. The
  1112	complete linear system of an invertible sheaf is the projective space of its nonzero global sections,
  1113	and its associated map is the map defined by those sections.
  1114	\end{proposition}
  1115	\begin{proof}
  1116	Locally trivialize the sheaf; the section is a non-zero-divisor equation and its local equations differ
  1117	by units. Ratios of a basis of global sections give the associated projective map.
  1118	\end{proof}
  1119	
  1120	\begin{lemma}[Base-point-free linear systems]
  1121	\label{lem:II-7-8}
  1122	\source{hartshorne-algebraic-geometry:II.7.8}
  1123	\dcref{II.7.8}
  1124	A linear system has no base points precisely when its sections generate the associated invertible
  1125	sheaf; in that case it defines a morphism to projective space.
  1126	\uses{thm:II-7-1}
  1127	\end{lemma}
  1128	\begin{proof}
  1129	The stalkwise generation condition is exactly the absence of a common zero, and Theorem~\ref{thm:II-7-1}
  1130	then constructs the morphism.
  1131	\end{proof}
  1132	
  1133	\begin{lemma}[Proj invariant under twisting]
  1134	\label{lem:II-7-9}
  1135	\source{hartshorne-algebraic-geometry:II.7.9}
  1136	\dcref{II.7.9}
  1137	For a graded ring $S$, $\operatorname{Proj}S\simeq\operatorname{Proj}S(d)$ after replacing the grading
  1138	by a positive twist; the standard opens and their structure sheaves are unchanged.
  1139	\end{lemma}
  1140	\begin{proof}
  1141	The homogeneous prime ideals and degree-zero localizations are unchanged by a common shift of degrees.
  1142	\end{proof}
